{
  "summary": "Con đã mở lời rõ ràng, nói được điều mình lo và cùng mẹ chọn một bước tiếp theo cụ thể. Đây là cách trao đổi bình tĩnh, giúp mẹ hiểu con cần gì.",
  "strengths": [
    "Con báo trước rằng có chuyện muốn kể và nói rõ điều con đang lo: “Con lo mẹ sẽ thu điện thoại trước khi nghe hết.”",
    "Con nêu điều mình trực tiếp biết—có bạn đăng ảnh chế con trong nhóm lớp—rồi nói rõ mình muốn mẹ lắng nghe và cùng chọn bước nhỏ.",
    "Con đưa ra đề nghị cụ thể, chưa muốn nhắn cho phụ huynh bạn ấy ngay.",
    "Con chọn bước tiếp theo rõ ràng: lưu ảnh chụp và ngày mai cùng mẹ nói riêng với cô chủ nhiệm."
  ],
  "suggestions": [
    "Khi kể thêm, con có thể nói những chi tiết con trực tiếp thấy, như bài đăng ở nhóm nào, khoảng thời gian nào và nội dung gì; phân biệt rõ điều con biết với điều con chưa chắc.",
    "Nếu thấy phù hợp, con có thể nói thêm chuyện này ảnh hưởng đến con ra sao và con mong mẹ hỗ trợ điều gì trước mắt.",
    "Khi lưu ảnh chụp, hãy giữ nguyên nội dung và thông tin liên quan như thời gian đăng, tên nhóm; có thể nhờ mẹ cùng kiểm tra để chuẩn bị kể với cô."
  ],
  "rephrasings": [
    {
      "original": "Mẹ ơi, con có chuyện trên mạng muốn kể. Con lo mẹ sẽ thu điện thoại trước khi nghe hết.",
      "better": "Mẹ ơi, con có chuyện trên mạng muốn kể. Con đang lo về chuyện điện thoại; mẹ nghe con kể hết trước rồi mình cùng bàn nhé?",
      "why": "Cách nói này vẫn chia sẻ nỗi lo, đồng thời đưa ra một đề nghị cụ thể để mẹ có thể đáp lại."
    },
    {
      "original": "Có bạn đăng ảnh chế con trong nhóm lớp.",
      "better": "Con thấy có ảnh chế con được đăng trong nhóm lớp. Con có thể kể mẹ biết con thấy bài đó khi nào và ở nhóm nào không?",
      "why": "Cách nói này làm rõ đây là điều con trực tiếp thấy và mở đường để bổ sung chi tiết cần thiết."
    }
  ],
  "follow_ups": [
    "Cùng mẹ ghi lại những gì con trực tiếp biết và chuẩn bị một câu mở đầu để nói riêng với cô chủ nhiệm vào ngày mai.",
    "Nếu muốn luyện thêm, hãy thử tập cách trả lời khi mẹ hỏi thêm chi tiết hoặc đề xuất một bước khác."
  ],
  "safety_note": null
}

{
  "summary": "Bạn đã nói rõ điều mình trực tiếp biết và chủ động xin hỗ trợ cụ thể. Đây là cách trao đổi thận trọng, tập trung vào sự việc và giúp người lớn hiểu bạn cần gì.",
  "strengths": [
    "Bạn nêu rõ vai trò của mình: “Cháu là người chứng kiến”, thay vì khẳng định điều mình không trực tiếp biết.",
    "Bạn nói rõ giới hạn thông tin: “không chắc ai bắt đầu”, giúp tránh suy đoán hoặc quy kết.",
    "Bạn chia sẻ nỗi lo bị gây khó dễ, để cô có thể cùng bạn tính đến sự an toàn và riêng tư.",
    "Bạn đưa ra đề nghị cụ thể: hẹn nói chuyện riêng, hỏi cách giữ kín danh tính và thống nhất thời điểm theo dõi lại."
  ],
  "suggestions": [
    "Trước khi gặp giáo viên, ghi lại những gì bạn nhớ như thời điểm, địa điểm và điều bạn trực tiếp nhìn thấy; nếu không nhớ rõ, cứ nói vậy.",
    "Cùng cô thống nhất trước bạn muốn cô hỗ trợ phần nào trong cuộc nói chuyện, chẳng hạn mở lời hoặc giúp ghi lại các bước tiếp theo.",
    "Hỏi giáo viên điều gì có thể được giữ kín và ai có thể cần biết, vì việc giữ kín danh tính có thể không được bảo đảm tuyệt đối.",
    "Thỏa thuận trước với cô sẽ làm gì nếu có bạn bè gây khó dễ sau buổi trao đổi, chẳng hạn báo cho cô hoặc một người lớn đáng tin khác."
  ],
  "rephrasings": [
    {
      "original": "Cháu sợ nhóm bạn sẽ gây khó dễ nếu biết cháu kể.",
      "better": "Cháu lo nhóm bạn có thể gây khó dễ nếu biết cháu đã kể. Cô giúp cháu nghĩ cách báo với giáo viên an toàn nhất được không?",
      "why": "Câu này giữ nguyên mối lo và thêm một đề nghị hỗ trợ cụ thể."
    },
    {
      "original": "Cô có thể cùng cháu hẹn nói chuyện riêng, hỏi cách giữ kín danh tính và thống nhất lúc theo dõi lại không?",
      "better": "Cô có thể giúp cháu hẹn nói chuyện riêng với giáo viên, hỏi ai sẽ biết thông tin và thống nhất khi nào mình kiểm tra lại tình hình không?",
      "why": "Cách nói này làm rõ hơn việc cần hỏi về phạm vi chia sẻ thông tin và bước theo dõi."
    }
  ],
  "follow_ups": [
    "Cùng cô ghi ngắn gọn những điều bạn trực tiếp thấy, kèm thời gian và địa điểm nếu nhớ.",
    "Luyện trước một câu mở đầu với cô, rồi thống nhất cách kết thúc buổi gặp bằng một bước tiếp theo cụ thể.",
    "Nếu tình hình tiếp diễn, ghi lại sự việc mới và trao đổi lại với cô hoặc giáo viên theo kế hoạch đã thống nhất."
  ],
  "safety_note": "Nếu có ai đe dọa hoặc bạn cảm thấy không an toàn, hãy báo ngay cho cô hoặc một người lớn đáng tin và tránh đối chất một mình. Khi cần hỗ trợ khẩn cấp hoặc thêm hướng dẫn, bạn có thể gọi Tổng đài bảo vệ trẻ em 111, miễn phí 24/24."
}

